#!/usr/bin/env python3
"""Bundle the whole architecture into ONE generated file: docs/ARCHITECTURE-FULL.md.

  python3 tools/bundle_architecture.py            # (re)generate the bundle
  python3 tools/bundle_architecture.py --check    # exit 1 if the bundle is stale against its sources

The bundle is DERIVED, never edited: its sources are docs/ARCHITECTURE.md (the base), docs/volumes/INDEX.md and the
design volumes docs/volumes/V01-*.md … V12-*.md (owner, 2026-09-28: "bundle them all together"; J89). Every source keeps
its own home, so a fact is still stated once; the bundle only puts them in one file, in reading order, with a generated
table of contents and the sha256 of every source so staleness is detectable.
"""
import glob, hashlib, os, re, sys

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P = lambda *a: os.path.join(BASE, *a)
OUT = P("docs", "ARCHITECTURE-FULL.md")


def sources():
    srcs = [P("docs", "ARCHITECTURE.md")]
    idx = P("docs", "volumes", "INDEX.md")
    if os.path.exists(idx):
        srcs.append(idx)
    srcs += sorted(glob.glob(P("docs", "volumes", "V[0-9][0-9]-*.md")))
    return srcs


def headings(text):
    """Top-level (#) and second-level (##) headings outside code fences."""
    out, fence = [], False
    for line in text.split("\n"):
        if line.lstrip().startswith("```"):
            fence = not fence
            continue
        if not fence and (line.startswith("# ") or line.startswith("## ")):
            out.append(line)
    return out


def anchor(h):
    t = re.sub(r"^#+\s*", "", h).strip().lower()
    t = re.sub(r"[^\w\s§.-]", "", t)
    return re.sub(r"\s+", "-", t)


def build():
    srcs = sources()
    parts, meta, toc = [], [], []
    volumes_begun = False
    for s in srcs:
        text = open(s, encoding="utf-8").read()
        rel = os.path.relpath(s, BASE)
        meta.append(f"| `{rel}` | {hashlib.sha256(text.encode()).hexdigest()[:16]} | {text.count(chr(10)) + 1} |")
        if rel.startswith("docs/volumes/") and not volumes_begun:
            volumes_begun = True
            part = "# PART IV — The design volumes (full build depth for every staged subject)"
            toc.append(f"- [{part[2:]}](#{anchor(part)})")
            parts.append(part + "\n\n*Generated from docs/volumes/ by tools/bundle_architecture.py — edit the volume files, never this copy.*\n")
        for h in headings(text):
            level = 0 if h.startswith("# ") else 1
            if rel.startswith("docs/volumes/"):
                level += 1
            toc.append("  " * level + f"- [{re.sub(r'^#+ ', '', h)}](#{anchor(h)})")
        parts.append(f"<!-- source: {rel} -->\n" + text.rstrip() + "\n")
    head = ["# THE WHOLE ARCHITECTURE — PLAT, base and design volumes in one file (GENERATED)", "",
            "> Generated by `python3 tools/bundle_architecture.py` (owner, 2026-09-28: \"bundle them all together\"; J89). "
            "Do not edit this file: edit its sources and regenerate. `--check` reports staleness.", "",
            "## Sources", "", "| file | sha256 (16) | lines |", "|---|---|---|", *meta, "", "## Contents", "", *toc, ""]
    return "\n".join(head) + "\n" + "\n".join(parts)


def main():
    new = build()
    if "--check" in sys.argv:
        old = open(OUT, encoding="utf-8").read() if os.path.exists(OUT) else ""
        stale = old != new
        print("STALE" if stale else "UP TO DATE", OUT)
        sys.exit(1 if stale else 0)
    open(OUT, "w", encoding="utf-8").write(new)
    print(f"wrote {os.path.relpath(OUT, BASE)}: {new.count(chr(10)) + 1} lines from {len(sources())} source(s)")


if __name__ == "__main__":
    main()
